import{_ as t,o as a,c as r,ag as i}from"./chunks/framework.D1K3FKSn.js";const c=JSON.parse('{"title":"WebGPU Notes","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/reference/webgpu.html"}],["meta",{"property":"og:title","content":"WebGPU Notes | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/reference/webgpu.html"}],["meta",{"name":"twitter:title","content":"WebGPU Notes | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"reference/webgpu.md","filePath":"reference/webgpu.md"}'),s={name:"reference/webgpu.md"};function n(o,e,l,d,h,p){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="webgpu-notes" tabindex="-1">WebGPU Notes <a class="header-anchor" href="#webgpu-notes" aria-label="Permalink to &quot;WebGPU Notes&quot;">​</a></h1><p>Why Kiln uses WebGPU, how it compares to WebGL for volume rendering, and future GPU optimization opportunities.</p><h2 id="webgpu-vs-webgl-for-volume-rendering" tabindex="-1">WebGPU vs WebGL for volume rendering <a class="header-anchor" href="#webgpu-vs-webgl-for-volume-rendering" aria-label="Permalink to &quot;WebGPU vs WebGL for volume rendering&quot;">​</a></h2><p>Kiln is built on WebGPU rather than WebGL. This section documents the technical differences relevant to volume rendering.</p><h3 id="_16-bit-and-float-texture-support" tabindex="-1">16-bit and float texture support <a class="header-anchor" href="#_16-bit-and-float-texture-support" aria-label="Permalink to &quot;16-bit and float texture support&quot;">​</a></h3><p>WebGPU&#39;s <code>r16float</code> format stores half-precision floats with hardware trilinear filtering, and is a core feature (no extension required). Kiln stores all 16-bit and float data in <code>r16float</code>: <code>uint16</code> values are converted to half-precision and <code>float32</code> inputs are repacked to half-precision on ingest.</p><p><strong>Fallback chain</strong>: Kiln detects format support at runtime:</p><ul><li><strong>r16float</strong> (preferred) — half-precision, filterable, core WebGPU</li><li><strong>r8unorm</strong> (last resort) — workers downsample 16→8 bit via high-byte extraction (<code>&gt;&gt; 8</code>)</li></ul><p>The r8unorm fallback triggers a console warning and shows <code>(⚠️ downsampled)</code> in the UI.</p><p>WebGL lacks native 16-bit single-channel textures. Common workarounds include:</p><ul><li><strong>Two-channel packing</strong>: Store high/low bytes in separate channels, reconstruct in shader</li><li><strong>Float textures</strong>: Use <code>R32F</code> (wastes memory, requires <code>OES_texture_float</code>)</li><li><strong>Half-float textures</strong>: Use <code>R16F</code> (different precision characteristics than integer)</li></ul><p>Each workaround adds shader complexity and may affect filtering behavior at brick boundaries.</p><h3 id="compute-shaders" tabindex="-1">Compute shaders <a class="header-anchor" href="#compute-shaders" aria-label="Permalink to &quot;Compute shaders&quot;">​</a></h3><p>WebGPU compute shaders enable per-pixel raymarching with explicit thread dispatch:</p><div class="language-wgsl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">wgsl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">compute</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> @</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">workgroup_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">builtin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(global_invocation_id) gid: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">vec3u</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // One thread per pixel, full control over execution</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>WebGL requires rendering a full-screen quad and performing raymarching in a fragment shader. This is functionally equivalent for the core raymarching loop, but compute shaders provide practical benefits for Kiln&#39;s pipeline:</p><ul><li><strong>Direct <code>textureStore</code> output</strong>: Write results to storage textures without framebuffer configuration</li><li><strong>Compute-to-compute chaining</strong>: The temporal accumulation pass reads the raymarcher&#39;s output and writes the blended result, all within compute. Fragment shaders would require render pass transitions and intermediate framebuffer management</li><li><strong>Cleaner resolution scaling</strong>: Dispatch fewer threads (e.g. 1440×810 instead of 1920×1080) rather than managing an intermediate framebuffer and blit-upscale</li><li><strong>No rasterizer overhead</strong>: No vertex shader, fullscreen triangle, or rasterization stage</li></ul><p>Kiln does not yet leverage compute-specific features like shared memory, subgroup operations, or indirect dispatch. The compute choice is an architectural investment in future headroom rather than a current necessity.</p><h3 id="asynchronous-texture-updates" tabindex="-1">Asynchronous texture updates <a class="header-anchor" href="#asynchronous-texture-updates" aria-label="Permalink to &quot;Asynchronous texture updates&quot;">​</a></h3><p>WebGPU&#39;s <code>device.queue.writeTexture()</code> queues texture uploads without blocking the CPU or stalling rendering. Multiple brick uploads can be batched and executed asynchronously.</p><p>WebGL&#39;s <code>texSubImage3D()</code> is synchronous on the CPU timeline. While the GPU may process it asynchronously, the CPU call blocks until the data is transferred to GPU-accessible memory. This can cause frame drops during intensive streaming.</p><h3 id="_3d-texture-limits" tabindex="-1">3D texture limits <a class="header-anchor" href="#_3d-texture-limits" aria-label="Permalink to &quot;3D texture limits&quot;">​</a></h3><p>WebGPU allows querying actual device limits via <code>device.limits.maxTextureDimension3D</code>. Modern GPUs commonly support 16384³, though this varies by hardware.</p><p>WebGL 2 specifies a minimum of 256³ for 3D textures, with most implementations supporting 2048³. Larger atlases may require multiple textures or texture arrays.</p><h3 id="integer-texture-formats" tabindex="-1">Integer texture formats <a class="header-anchor" href="#integer-texture-formats" aria-label="Permalink to &quot;Integer texture formats&quot;">​</a></h3><p>The indirection table uses <code>rgba8uint</code> format to store slot indices and LOD levels as exact integers. WebGPU provides <code>textureLoad()</code> for non-interpolated integer sampling.</p><p>WebGL 2 supports integer textures but with more limited format options and requires careful handling to avoid unintended filtering.</p><h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>WebGL 2</th><th>WebGPU</th></tr></thead><tbody><tr><td>16-bit / float textures</td><td>Emulated</td><td>Native <code>r16float</code></td></tr><tr><td>3D texture limit</td><td>Typically 2048³</td><td>Up to 16384³</td></tr><tr><td>Compute shaders</td><td>No</td><td>Yes (pipeline flexibility, future headroom)</td></tr><tr><td>Texture uploads</td><td>Synchronous</td><td>Asynchronous queue</td></tr><tr><td>Integer textures</td><td>Limited</td><td>Full support</td></tr></tbody></table><p>These differences don&#39;t make WebGL unsuitable for volume rendering—capable WebGL renderers exist. However, WebGPU provides a more direct mapping to the hardware capabilities needed for streaming virtual textures.</p>`,30)])])}const m=t(s,[["render",n]]);export{c as __pageData,m as default};
